"""Focused editorial revision; all numerical inputs remain the frozen evidence."""
import json

def revise(B,texts,tables,figures):
    texts['ABSTRACT']=('This study measures the contribution and computational cost of landmark search and final local adjustment in constrained body-route planning for a simulated hexapod. Six configurations share obstacle clearance, deadlines, nominal battery limits and terrain-exposure limits. Eight development maps select settings, and 32 main-test maps provide three repetitions per method, giving 640 planning attempts. The complete planner, V4, accepts 93 of 96 main-test attempts; coordinate-based particle swarm optimization, PSO-C, accepts 94. Removing final adjustment reduces acceptance to 90. Removing landmark search retains 93 and reduces mean search time from 0.376 to 0.196 s, while complete V4 has a 0.924% conditional mean score improvement over that reduced version. Against PSO-C, V4 has a mean paired-map score improvement of 0.690%, a zero median and a descriptive 95% bootstrap interval of [−0.255, 2.312]%, which includes zero. A separate sixteen-execution diagnostic completes four missions with each of full and half-scale body assistance; neither zero-assistance condition completes a mission within 180 s. Assisted executions detect no foot contact under the six-foot detector. The results identify configuration-specific planning trade-offs and assistance dependence. Battery costs are nominal model outputs, without physical or electrical validation.')
    texts['ALGORITHM']=('Algorithm 1. Complete V4 route search.\n\n'
      'Input: known geometry and terrain; start, goal and heading; mission limits; fixed return allowance; random seed; two-second and 240-evaluation ceilings.\n\n'
      '1. Run the initial resource-aware refiner within 40% of the time allowance. Charge its route evaluations to the common ceiling and retain its returned incumbent.\n\n'
      '2. Test the direct start-to-goal connection while budget remains. For each new route, reject invalid or blocked geometry, otherwise evaluate the common metrics and feasibility rank. Reuse cached evaluations for repeated geometry.\n\n'
      '3. Gather points from the incumbent, inflated obstacle corners and terrain boundaries. Remove duplicate and blocked points, rank extras by start-to-point plus point-to-goal distance, and retain at most 44 total nodes including endpoints.\n\n'
      '4. Build collision-free connections and search heading-aware routes using score, time and battery weights, within the landmark time allocation and expansion bound. Evaluate resulting complete routes with the common rank.\n\n'
      '5. Apply final local adjustment to the best route: test point deletion, projection, midpoint replacement and directional moves at 0.75, 0.25 and 0.08 m. Retain only better rankings; stop at the common budget or at most three passes per step size.\n\n'
      'Output: the best retained route and its metrics, or the initial search status when no route is retained. An accepted route always ranks ahead of a rejected one.')
    texts['FRESH_RESULTS']=('All 640 planning attempts finish without a recorded trial error, and development selects the default profile for every base method. Table 2 reports all main-test acceptance counts and mean search times. V4, PSO-P, ACO-P and V4 noL each accept 93/96 attempts; PSO-C accepts 94/96 and V4 noP accepts 90/96. Every rejected main-test attempt fails a resource requirement.')
    texts['PAIRED_RESULTS']=('Against PSO-C, V4 has 33 lower-score paired accepted attempts, 27 ties and 33 higher-score attempts. PSO-C alone accepts one attempt; V4 alone accepts none, and both reject two. The paired-map mean difference is 0.690%, the median is zero and the descriptive 95% interval is [−0.255, 2.312]%. The interval includes zero.\n\n'
      'Table 3 reports means and intervals for all five comparisons. The PSO-P and ACO-P comparisons both have zero medians. Against V4 noL, complete V4 has 27 lower-score attempts, 57 ties and nine higher-score attempts. Against V4 noP, it has 57 lower-score attempts, 33 ties and no higher-score attempts, together with three attempts accepted only by complete V4. Thus the score and acceptance effects of each removed stage remain separate outcomes.')
    texts['FAMILY_RESULTS']=('All resource rejections occur in corridor maps. Open, clutter and rough maps each give 24/24 accepted attempts for every method. Corridor acceptance is 21/24 for V4, PSO-P, ACO-P and V4 noL, 22/24 for PSO-C and 18/24 for V4 noP. Each map type contributes eight maps and three repetitions. These counts locate both PSO-C’s extra acceptance and the three acceptances lost after removing final adjustment.')
    texts['COMPUTE_RESULTS']=('Table 4 reports search work across all 96 attempts per method. PSO-C reaches the 240-route evaluation ceiling on 84/96 attempts; none of the other methods reaches it. Median route-evaluation counts are 33 for V4 and 21 after landmark removal. Median geometric-clearance checks are 1,033 for V4, 2,142.5 for PSO-C and 146.5 for V4 noL. Shared map preparation takes a median of 0.715 s and a maximum of 0.895 s, outside the individual search timers. A route evaluation computes full-route metrics, whereas a clearance query can reject a segment before a complete route is evaluated.')
    texts['SENSITIVITY_RESULTS']=('Figure 2 shows all 31 paired-map effects against PSO-C, ranging from −1.718% to 23.202%. Map 24 supplies the largest positive effect. Leaving it out changes the remaining-map mean from 0.690% to −0.060%. For the noP comparison, the means obtained by leaving out one map at a time remain positive, ranging from 0.682% to 0.822%. These are post-hoc influence summaries of the unchanged main-test sample.')
    a=json.loads((B/'results/map24_analysis.json').read_text());v=a['means']['proposed_v4'];c=a['means']['continuous_pso']
    texts['CASE_RESULTS']=(f'Map 24 is a corridor map on which both methods accept all three repetitions. V4 returns the same route in every repetition, with distance {v["distance_m"]:.3f} m and score {v["quality_score"]:.3f}; PSO-C’s corresponding mean values are {c["distance_m"]:.3f} m and {c["quality_score"]:.3f}. V4’s mean predicted time, nominal battery cost and exposure are {v["estimated_seconds"]:.3f} s, {v["energy_percent"]:.3f} points and {v["terrain_exposure"]:.3f}, compared with {c["estimated_seconds"]:.3f} s, {c["energy_percent"]:.3f} points and {c["terrain_exposure"]:.3f} for PSO-C.\n\n'
      'V4 has lower values of all four score components in every paired repetition. Figure 3 shows repetition zero: PSO-C takes a wider detour to the west. This explains the score difference for that returned route without identifying a unique internal cause in the optimizer.')
    texts['PROBE_RESULTS']=('Full and half-scale assistance each complete 4/4 missions. Both zero-assistance conditions complete 0/4, with all unfinished missions timing out at 180 s. Table 5 combines completion and foot-contact measurements for the sixteen valid executions. GC denotes leg-body gravity compensation. Each contact range summarizes four missions; mean feet is the average detected foot count per physics sample, and no-contact percentage is the fraction of samples with zero detected foot contacts. Contacts involving other robot parts are outside this detector.')
    texts['REPLAY_DETAIL']=('Full-assistance mission distances are 34.71–42.83 m, with elapsed times of 62.85–89.63 s; half-scale values are 34.75–42.91 m and 62.83–89.66 s. Completed times include eight seconds of station service. At zero assistance, displacement by the timeout is 0.324–0.326 m with compensation and 0.376–0.381 m without it. Assisted runs have maximum tilt below 0.410 degrees while roll and pitch are directly corrected.')
    texts['CONCLUSION_RESULTS']=('Under the fixed 32-map main-test protocol, final local adjustment increases acceptance from 90 to 93 of 96 attempts. Landmark search preserves that acceptance count and adds search time for a 0.924% paired mean score benefit over its removal. The two stage-removal comparisons therefore identify different acceptance, score and computation trade-offs. V4 does not establish a mean score advantage over PSO-C: its 0.690% paired-map mean has a zero median and a descriptive interval spanning zero, while PSO-C accepts one additional attempt.')
    tables['TABLE_SETTINGS']=('Table 1. Selected search settings; noL omits landmark search and noP omits final adjustment.',[
      ['Method','Search settings','Final adjustment'],
      ['V4','Initial fraction 0.40; landmark fraction 0.32; 44 nodes; initial beam 6, labels/state 8, candidates 16','Steps 0.75, 0.25, 0.08 m'],
      ['V4 noL','V4 initial settings; no landmark stage','Same as V4'],
      ['V4 noP','V4 initial and landmark settings','Omitted'],
      ['PSO-P','16 particles; 40 iterations/corridor; inertia 0.72; coefficients 1.49; velocity clip 0.25','Same as V4'],
      ['ACO-P','12 ants; 40 iterations/corridor; pheromone/heuristic exponents 1/2; evaporation 0.20; deposit 1','Same as V4'],
      ['PSO-C','12 particles; 40 iterations; inertia 0.65; coefficients 1.4; perturbation and velocity clip 2 m','Last 25% of time; V4 steps']])
    tables['TABLE_COMPUTE']=('Table 4. Search work over 96 attempts; evaluations count complete collision-free routes.',tables['TABLE_COMPUTE'][1])
    contact=tables['TABLE_CONTACT'][1][1:];outcomes=tables['TABLE_PROBE'][1][1:]
    tables['TABLE_MOTION']=('Table 5. Completion and foot-contact ranges across four missions per condition.',[['Condition','Done / 4','Mean feet','No-contact (%)']]+[[r[0],r[1],co[1],co[2]] for r,co in zip(outcomes,contact)])
    keep={'TABLE_SETTINGS','TABLE_PRIMARY','TABLE_PAIRED','TABLE_COMPUTE','TABLE_MOTION'}
    for key in list(tables):
        if key not in keep:del tables[key]
    figures['FIG_DISTRIBUTION']=(figures['FIG_DISTRIBUTION'][0],'Figure 2. V4 score difference against PSO-C on every paired map, averaged over jointly accepted repetitions. Positive values favor V4. All points remain in the primary mean.')
    figures['FIG_CASE']=(figures['FIG_CASE'][0],'Figure 3. Routes on corridor map 24, repetition 0. The circle and star mark start and destination; black blocks are obstacles and amber regions are terrain. This case is selected post hoc for its largest positive paired-map effect.')
    for key in list(figures):
        if key not in {'FIG_OVERVIEW','FIG_DISTRIBUTION','FIG_CASE'}:del figures[key]
    assert len(texts['ABSTRACT'].split())<=250
